const { domain, name, description } = $.input;

if (!domain) throw new Error('domain is required');

const values = {
  domains: [{ domain: domain, root_domain: domain }]
};

if (name) {
  values.name = [{ value: name }];
}

if (description) {
  values.description = [{ value: description }];
}

return { values };

const resp = $.steps.upsertCompany.response || {};
const data = resp.data || {};
const id = data.id || {};

return {
  recordId: id.record_id || '',
  objectId: id.object_id || '',
  webUrl: data.web_url || '',
  createdAt: data.created_at || '',
  domain: $.input.domain,
  summary: id.record_id
    ? `Upserted company ${$.input.domain} (${id.record_id})`
    : 'Failed to upsert company'
};
